// Embedded 3D PCB viewer for klepcbgen. Loads the GLB generated by kicad-cli
// into a three.js scene with orbit/zoom/pan controls.
import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/GLTFLoader.module.js';
import { OrbitControls } from 'three/addons/OrbitControls.module.js';

let renderer = null;
let scene = null;
let camera = null;
let controls = null;

function initViewer(canvas) {
  renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
  renderer.setPixelRatio(window.devicePixelRatio);
  renderer.outputColorSpace = THREE.SRGBColorSpace;

  scene = new THREE.Scene();
  scene.background = new THREE.Color(0x171a21);

  // GLB from kicad-cli uses meters (board ~0.3m wide), so the near plane must
  // be far smaller than the default to avoid clipping the small model.
  camera = new THREE.PerspectiveCamera(50, 1, 0.001, 1000);
  camera.position.set(60, 45, 80);

  controls = new OrbitControls(camera, canvas);
  controls.enableDamping = true;
  controls.dampingFactor = 0.08;

  const hemi = new THREE.HemisphereLight(0xffffff, 0x334155, 0.9);
  scene.add(hemi);
  // Key light from above (top of board).
  const key = new THREE.DirectionalLight(0xffffff, 1.2);
  key.position.set(80, 120, 100);
  scene.add(key);
  // Second key light from below so the underside of the PCB is lit too.
  const keyBottom = new THREE.DirectionalLight(0xffffff, 1.2);
  keyBottom.position.set(-60, -120, -80);
  scene.add(keyBottom);
  const rim = new THREE.DirectionalLight(0x8ab4ff, 0.5);
  rim.position.set(-80, 40, -60);
  scene.add(rim);

  animate();
}

function animate() {
  requestAnimationFrame(animate);
  if (controls) controls.update();
  if (renderer) renderer.render(scene, camera);
}

function fitCamera(obj) {
  const box = new THREE.Box3().setFromObject(obj);
  const size = box.getSize(new THREE.Vector3());
  const center = box.getCenter(new THREE.Vector3());
  const maxDim = Math.max(size.x, size.y, size.z) || 1;
  const fov = camera.fov * Math.PI / 180;
  const dist = (maxDim / 2) / Math.tan(fov / 2);
  camera.position.copy(center).add(new THREE.Vector3(dist * 1.2, dist * 0.9, dist * 1.2));
  controls.target.copy(center);
  controls.update();
}

function show3D(url) {
  const preview = document.getElementById('preview');
  const canvas = document.getElementById('pcb3d');
  const placeholder = document.getElementById('placeholder');

  // Clear any previously loaded model.
  if (scene) {
    const toRemove = scene.children.filter(
      (c) => !c.isLight && c.type !== 'Scene' && !(c.isCamera)
    );
    toRemove.forEach((c) => scene.remove(c));
  }

  placeholder.style.display = 'none';
  canvas.style.display = 'block';

  if (!renderer) initViewer(canvas);

  const w = preview.clientWidth || 600;
  const h = preview.clientHeight || 460;
  renderer.setSize(w, h, false);

  new GLTFLoader().load(
    url,
    (gltf) => {
      scene.add(gltf.scene);
      fitCamera(gltf.scene);
    },
    undefined,
    (err) => {
      canvas.style.display = 'none';
      placeholder.style.display = 'grid';
      placeholder.innerHTML = '<div class="errorbox">3D preview failed to load.</div>';
    }
  );
}

window.show3D = show3D;
